<script setup lang="ts">
import AcademicNav from '@/Components/AcademicNav.vue'; import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, useForm } from '@inertiajs/vue3'; const props=defineProps<{subject?:any}>(); const form=useForm({name:props.subject?.name??'',code:props.subject?.code??'',description:props.subject?.description??'',sort_order:props.subject?.sort_order??100,status:props.subject?.status??'active'}); const submit=()=>props.subject?form.patch(route('academic.subjects.update',props.subject.id)):form.post(route('academic.subjects.store'));
</script>
<template><Head :title="subject?'Edit Subject':'Add Subject'"/><AuthenticatedLayout><h1 class="h2">{{subject?'Edit custom subject':'Add custom subject'}}</h1><AcademicNav/><form class="card" @submit.prevent="submit"><div class="card-body"><div class="row g-3"><div class="col-md-8"><label for="subject-name" class="form-label">Name</label><input id="subject-name" v-model="form.name" class="form-control" required></div><div class="col-md-4"><label for="subject-code" class="form-label">Stable code</label><input id="subject-code" v-model="form.code" class="form-control" required aria-describedby="subject-code-help"><small id="subject-code-help" class="text-secondary">Uppercase letters, numbers, underscores, and dashes.</small><div v-if="form.errors.code" class="invalid-feedback d-block">{{form.errors.code}}</div></div><div class="col-md-4"><label for="subject-order" class="form-label">Sort order</label><input id="subject-order" v-model.number="form.sort_order" type="number" min="0" class="form-control"></div><div class="col-md-4"><label for="subject-status" class="form-label">Status</label><select id="subject-status" v-model="form.status" class="form-select"><option value="active">Active</option><option value="retired">Retired</option></select></div><div class="col-12"><label for="subject-description" class="form-label">Description</label><textarea id="subject-description" v-model="form.description" class="form-control"/></div></div></div><div class="card-footer bg-white text-end"><Link class="btn btn-outline-secondary me-2" :href="route('academic.subjects.index')">Cancel</Link><button class="btn btn-primary" :disabled="form.processing">Save subject</button></div></form></AuthenticatedLayout></template>
